-- tres ejemplos para probar la papelera sin tocar los veinte productos activos
IF NOT EXISTS(SELECT 1 FROM dbo.Categorias WHERE Nombre=N'Categoria archivada')
BEGIN
    EXEC dbo.sp_Categoria_Agregar N'Categoria archivada',N'Ejemplo para restaurar desde la papelera.',@Id OUTPUT;
    EXEC dbo.sp_Categoria_Eliminar @Id;
END;
IF NOT EXISTS(SELECT 1 FROM dbo.Suplidores WHERE NombreEmpresa=N'Suplidor archivado')
BEGIN
    EXEC dbo.sp_Suplidor_Agregar N'Suplidor archivado',N'Carlos Pérez',N'849-555-6060',N'info@archivo.example',N'',@Id OUTPUT;
    EXEC dbo.sp_Suplidor_Eliminar @Id;
END;
IF NOT EXISTS(SELECT 1 FROM dbo.Productos WHERE Nombre=N'Producto archivado')
BEGIN
    SELECT @CategoriaId=Id FROM dbo.Categorias WHERE Nombre=N'Tecnología';
    SELECT @SuplidorId=Id FROM dbo.Suplidores WHERE NombreEmpresa=N'Suministros del Caribe';
    EXEC dbo.sp_Producto_Agregar N'Producto archivado',100,@CategoriaId,@SuplidorId,@Id OUTPUT;
    EXEC dbo.sp_Producto_Eliminar @Id;
END;
GO
SELECT 'Categorias activas' AS Grupo,COUNT(*) AS Cantidad FROM dbo.Categorias WHERE Activo=1
UNION ALL SELECT 'Suplidores activos',COUNT(*) FROM dbo.Suplidores WHERE Activo=1
UNION ALL SELECT 'Productos activos',COUNT(*) FROM dbo.Productos WHERE Activo=1;
GO

